const researchBody = (subject: string, action: string, signal: string): string[] => [
  `Methodology: this desk research maps ${subject} to repeatable tier-one helpdesk work. It uses the ten authoritative references below, then turns their principles into practical guidance for OutsourcedHelpdeskServices.com. It is not legal, security, or compliance advice.`,
  `Headline research signal: ${signal}. This count describes the operating model proposed here, not a universal benchmark. Validate it against your tools, risk profile, and named owner.`,
  `Start with a narrow queue. Define request types, the approved answer, required evidence, the stopping point, and the exception owner. ${action} should be documented before live access is granted.`,
  'Use least privilege and named accounts. Grant only the records and functions required for the lane, with MFA where available. Avoid shared credentials, copied secrets, and informal permission grants in chat.',
  'Make escalation a useful handoff: include impact, verification steps, timestamps, screenshots when necessary, actions already taken, and the decision needed from the receiving owner.',
  'Review a small sample of completed tickets daily during the first week, then weekly once stable. Score accuracy, evidence, tone, status, access boundaries, and whether the next owner can act without reopening the investigation.',
  'Keep personal data to the minimum needed. Redact unnecessary identifiers from notes and screenshots, set retention expectations, and document how a suspected security or privacy incident reaches its owner.',
  'Update the article, routing rule, or access boundary when the same miss appears twice. Improve the system that produced the ticket, not only the individual reminder.',
];
